// @FIGURE_CODE_BEGIN
/* ── Element spec ──────────────────────────────────────────────────────────
   box fill          → BoxGeometry(1,3,3) scaled in x by Δx, MeshPhysicalMaterial teal #b8dcd8 a=0.35
   depth occluder    → same BoxGeometry, colorWrite:false depthWrite:true (hides rear edges)
   visible edges     → LineSegments(EdgesGeometry) #2f8f8c depthTest on
   hidden edges      → LineSegments(EdgesGeometry) #2f8f8c opacity .22 depthTest off
   6 face pickers    → PlaneGeometry overlays, opacity 0 → 0.5 warm yellow #f2c14e when picked
   normal arrow      → cylinder+cone, dark grey, outward from picked face
   dim brackets (3)  → Line + end ticks + 2 cones, black  ('l' vertical, 'l' depth, 'Δx')
   triad @ x=0       → 3 red cylinder+cone arrows (+y,+x,+z) len 0.9
   triad @ x=Δx      → same, translated by Δx
   dashed x axis     → Line(LineDashedMaterial) through both triad origins + big cone head
   axis key          → 3 short black arrows (len .5) upper right, world space
   leaders Side1/2   → QuadraticBezier Line + cone head, rebuilt with Δx
   labels            → addLabel HTML, italic serif, 14–16px
──────────────────────────────────────────────────────────────────────────── */

const C_FILL = 0xb8dcd8, C_EDGE = 0x2f8f8c, C_RED = 0xe8402a,
      C_BLACK = 0x1a1a1a, C_HL = 0xf2c14e, C_NRM = 0x3a3a3a;
const L = 3.0, AXEXT = 1.7;
let DX = 1.2;

scene.add(new THREE.AmbientLight(0xffffff, 0.92));
const _dl = new THREE.DirectionalLight(0xffffff, 0.32); _dl.position.set(4, 6, 3); scene.add(_dl);

const UP = new THREE.Vector3(0, 1, 0);
function orientTo(m, dir) { m.quaternion.setFromUnitVectors(UP, dir.clone().normalize()); }

function makeArrow(dir, len, color, o = {}) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 1, depthTest: false });
  const sR = o.shaftR ?? 0.026, hR = o.headR ?? 0.088, hL = o.headL ?? 0.23;
  const sh = new THREE.Mesh(new THREE.CylinderGeometry(sR, sR, Math.max(0.001, len - hL), 12), mat);
  sh.position.y = (len - hL) / 2;
  const hd = new THREE.Mesh(new THREE.ConeGeometry(hR, hL, 18), mat);
  hd.position.y = len - hL / 2;
  g.add(sh, hd); g.renderOrder = 8;
  orientTo(g, dir);
  g.userData.mat = mat;
  return g;
}

function setLine(line, a, b) {
  const p = line.geometry.attributes.position.array;
  p[0] = a.x; p[1] = a.y; p[2] = a.z; p[3] = b.x; p[4] = b.y; p[5] = b.z;
  line.geometry.attributes.position.needsUpdate = true;
  line.geometry.computeBoundingSphere();
}
function blankSeg() {
  return new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
}

/* ── Box ─────────────────────────────────────────────────────────────────── */
const boxGroup = new THREE.Group();
scene.add(boxGroup);
const boxGeo = new THREE.BoxGeometry(1, L, L);

const occl = new THREE.Mesh(boxGeo, new THREE.MeshBasicMaterial({
  colorWrite: false, depthWrite: true, polygonOffset: true,
  polygonOffsetFactor: 1, polygonOffsetUnits: 2
}));
occl.renderOrder = 0; boxGroup.add(occl);

const fillMat = new THREE.MeshPhysicalMaterial({
  color: C_FILL, transparent: true, opacity: 0.35, depthWrite: false,
  side: THREE.DoubleSide, roughness: 0.6, metalness: 0.0
});
const fillMesh = new THREE.Mesh(boxGeo, fillMat);
fillMesh.renderOrder = 2; boxGroup.add(fillMesh);

const edgeGeo = new THREE.EdgesGeometry(boxGeo);
const edgesHidden = new THREE.LineSegments(edgeGeo, new THREE.LineBasicMaterial({
  color: C_EDGE, transparent: true, opacity: 0.22, depthTest: false
}));
edgesHidden.renderOrder = 1; boxGroup.add(edgesHidden);
const edgesVis = new THREE.LineSegments(edgeGeo, new THREE.LineBasicMaterial({ color: C_EDGE }));
edgesVis.renderOrder = 3; boxGroup.add(edgesVis);

/* ── Face pickers ────────────────────────────────────────────────────────── */
const EPS = 0.004;
function facePlane(w, h, pos, rot) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), new THREE.MeshBasicMaterial({
    color: C_HL, transparent: true, opacity: 0, side: THREE.DoubleSide, depthTest: false
  }));
  m.position.copy(pos); m.rotation.set(rot[0], rot[1], rot[2]); m.renderOrder = 4;
  boxGroup.add(m); return m;
}
const FACES = [
  { key: 'S3', name: 'Side 3', mesh: facePlane(L, L, new THREE.Vector3(-0.5 + EPS, 0, 0), [0, -Math.PI / 2, 0]), n: new THREE.Vector3(-1, 0, 0), flux: 'Φ = −E<sub>x</sub>(x,t)·l²', row: 'rowS3', comp: 'x',
    body: 'Side 3 is the large face at x, area l². Its outward normal is −x̂, so only the Ex component threads it: Φ₃ = −Ex(x,t)·l² (flux entering the box).' },
  { key: 'S4', name: 'Side 4', mesh: facePlane(L, L, new THREE.Vector3(0.5 - EPS, 0, 0), [0, Math.PI / 2, 0]), n: new THREE.Vector3(1, 0, 0), flux: 'Φ = +E<sub>x</sub>(x+Δx,t)·l²', row: 'rowS4', comp: 'x',
    body: 'Side 4 is the large face at x+Δx, area l², outward normal +x̂. Φ₄ = +Ex(x+Δx,t)·l² (flux leaving the box). Sides 3 and 4 are the only faces Ex can pierce.' },
  { key: 'S2', name: 'Side 2', mesh: facePlane(1, L, new THREE.Vector3(0, L / 2 - EPS, 0), [-Math.PI / 2, 0, 0]), n: new THREE.Vector3(0, 1, 0), flux: 'Φ = +E<sub>y</sub>·Δx·l', row: 'rowS2', comp: 'y',
    body: 'Side 2 is the top face, area Δx·l, outward normal +ŷ. Only Ey pierces it: Φ₂ = +Ey·Δx·l. It is exactly cancelled by Side 1 because Ey does not vary with y.' },
  { key: 'S1', name: 'Side 1', mesh: facePlane(1, L, new THREE.Vector3(0, -L / 2 + EPS, 0), [Math.PI / 2, 0, 0]), n: new THREE.Vector3(0, -1, 0), flux: 'Φ = −E<sub>y</sub>·Δx·l', row: 'rowS1', comp: 'y',
    body: 'Side 1 is the bottom face, area Δx·l, outward normal −ŷ: Φ₁ = −Ey·Δx·l. Equal and opposite to Side 2, so the pair contributes nothing net.' },
  { key: 'ZF', name: 'z-face (far)', mesh: facePlane(1, L, new THREE.Vector3(0, 0, L / 2 - EPS), [0, 0, 0]), n: new THREE.Vector3(0, 0, 1), flux: 'Φ = +E<sub>z</sub>·Δx·l', row: 'rowSZ', comp: 'z',
    body: 'A narrow z-normal face, area Δx·l, outward normal +ẑ: Φ = +Ez·Δx·l. Its partner at the other end of z gives −Ez·Δx·l, so the pair cancels.' },
  { key: 'ZN', name: 'z-face (near)', mesh: facePlane(1, L, new THREE.Vector3(0, 0, -L / 2 + EPS), [0, Math.PI, 0]), n: new THREE.Vector3(0, 0, -1), flux: 'Φ = −E<sub>z</sub>·Δx·l', row: 'rowSZ', comp: 'z',
    body: 'The other narrow z-normal face, area Δx·l, outward normal −ẑ: Φ = −Ez·Δx·l — equal and opposite to its partner.' }
];

const normalArrow = makeArrow(new THREE.Vector3(1, 0, 0), 0.95, C_NRM, { shaftR: 0.03, headR: 0.105, headL: 0.26 });
normalArrow.visible = false; scene.add(normalArrow);

/* ── Dimension brackets ──────────────────────────────────────────────────── */
function makeDim() {
  const g = new THREE.Group(); g.renderOrder = 7;
  const mat = new THREE.LineBasicMaterial({ color: C_BLACK, transparent: true, depthTest: false });
  const cmat = new THREE.MeshBasicMaterial({ color: C_BLACK, transparent: true, depthTest: false });
  const main = new THREE.Line(blankSeg(), mat);
  const t0 = new THREE.Line(blankSeg(), mat), t1 = new THREE.Line(blankSeg(), mat);
  const cg = new THREE.ConeGeometry(0.055, 0.18, 12);
  const c0 = new THREE.Mesh(cg, cmat), c1 = new THREE.Mesh(cg, cmat);
  g.add(main, t0, t1, c0, c1);
  g.update = (p0, p1, tick) => {
    setLine(main, p0, p1);
    setLine(t0, p0.clone().sub(tick), p0.clone().add(tick));
    setLine(t1, p1.clone().sub(tick), p1.clone().add(tick));
    const dir = p1.clone().sub(p0).normalize();
    c0.position.copy(p0).addScaledVector(dir, 0.09); orientTo(c0, dir.clone().negate());
    c1.position.copy(p1).addScaledVector(dir, -0.09); orientTo(c1, dir);
  };
  scene.add(g); return g;
}
const dimHeight = makeDim();
dimHeight.update(new THREE.Vector3(0, -L / 2, L + 0.38), new THREE.Vector3(0, L / 2, L + 0.38), new THREE.Vector3(0, 0, 0.17));
const dimDepth = makeDim();
dimDepth.update(new THREE.Vector3(0, L / 2 + 0.32, 0), new THREE.Vector3(0, L / 2 + 0.32, L), new THREE.Vector3(0, 0.15, 0));
const dimThick = makeDim();

/* ── Field triads ────────────────────────────────────────────────────────── */
const TRI_Y = 0.1, TRI_Z = 1.2, ALEN = 0.9;
function makeTriad() {
  const g = new THREE.Group();
  const ax = makeArrow(new THREE.Vector3(1, 0, 0), ALEN, C_RED);
  const ay = makeArrow(new THREE.Vector3(0, 1, 0), ALEN, C_RED);
  const az = makeArrow(new THREE.Vector3(0, 0, 1), ALEN, C_RED);
  g.add(ax, ay, az); scene.add(g);
  g.userData = { ax, ay, az };
  return g;
}
const triadL = makeTriad(); triadL.position.set(0, TRI_Y, TRI_Z);
const triadR = makeTriad(); triadR.position.set(DX, TRI_Y, TRI_Z);

/* ── Dashed x axis ───────────────────────────────────────────────────────── */
const dashMat = new THREE.LineDashedMaterial({ color: 0x111111, dashSize: 0.15, gapSize: 0.1, transparent: true, depthTest: false });
const dashLine = new THREE.Line(new THREE.BufferGeometry(), dashMat);
dashLine.renderOrder = 7; scene.add(dashLine);
const dashHead = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.28, 18),
  new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true, depthTest: false }));
dashHead.renderOrder = 7; orientTo(dashHead, new THREE.Vector3(1, 0, 0)); scene.add(dashHead);

/* ── Curved leaders ──────────────────────────────────────────────────────── */
function makeLeader() {
  const g = new THREE.Group(); g.renderOrder = 7;
  const line = new THREE.Line(new THREE.BufferGeometry(),
    new THREE.LineBasicMaterial({ color: C_BLACK, transparent: true, depthTest: false }));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.065, 0.2, 14),
    new THREE.MeshBasicMaterial({ color: C_BLACK, transparent: true, depthTest: false }));
  g.add(line, head); scene.add(g);
  g.update = (p0, p1, p2) => {
    const pts = new THREE.QuadraticBezierCurve3(p0, p1, p2).getPoints(40);
    const old = line.geometry;
    line.geometry = new THREE.BufferGeometry().setFromPoints(pts);
    old?.dispose?.();
    const tan = pts[pts.length - 1].clone().sub(pts[pts.length - 3]).normalize();
    head.position.copy(pts[pts.length - 1]).addScaledVector(tan, -0.08);
    orientTo(head, tan);
  };
  return g;
}
const leader2 = makeLeader();
const leader1 = makeLeader();

/* ── Axis key (upper right, world space) ─────────────────────────────────── */
const KEY = new THREE.Vector3(2.3, 1.9, -0.5);
const keyGroup = new THREE.Group(); keyGroup.position.copy(KEY); scene.add(keyGroup);
['x', 'y', 'z'].forEach(k => {
  const dir = new THREE.Vector3(k === 'x' ? 1 : 0, k === 'y' ? 1 : 0, k === 'z' ? 1 : 0);
  keyGroup.add(makeArrow(dir, 0.5, 0x111111, { shaftR: 0.017, headR: 0.058, headL: 0.15 }));
});

/* ── Label helper ────────────────────────────────────────────────────────── */
function lbl(html, pos, opts = {}) {
  const e = addLabel(html, pos, Object.assign({ color: '#1a1a1a', fontSize: '14px' }, opts));
  e.div.style.fontFamily = 'Georgia, "Times New Roman", serif';
  e.div.style.fontStyle = opts.italic === false ? 'normal' : 'italic';
  return e;
}

/* ── Labels ──────────────────────────────────────────────────────────────── */
const lEyL = lbl('<i>E<sub>y</sub></i>(<i>x</i>,<i>t</i>)', new THREE.Vector3(0, TRI_Y + ALEN, TRI_Z), { color: '#e8402a', offset: [46, -8] });
const lExL = lbl('<i>E<sub>x</sub></i>(<i>x</i>,<i>t</i>)', new THREE.Vector3(ALEN, TRI_Y, TRI_Z), { color: '#e8402a', offset: [-22, 20] });
const lEzL = lbl('<i>E<sub>z</sub></i>(<i>x</i>,<i>t</i>)', new THREE.Vector3(0, TRI_Y, TRI_Z + ALEN), { color: '#e8402a', offset: [-32, 18] });

const lEyR = lbl('<i>E<sub>y</sub></i>(<i>x</i>+Δ<i>x</i>,<i>t</i>)', new THREE.Vector3(DX, TRI_Y + ALEN, TRI_Z), { color: '#e8402a', offset: [8, -16] });
const lExR = lbl('<i>E<sub>x</sub></i>(<i>x</i>+Δ<i>x</i>,<i>t</i>)', new THREE.Vector3(DX + ALEN, TRI_Y, TRI_Z), { color: '#e8402a', offset: [-6, 20] });
const lEzR = lbl('<i>E<sub>z</sub></i>(<i>x</i>+Δ<i>x</i>,<i>t</i>)', new THREE.Vector3(DX, TRI_Y, TRI_Z + ALEN), { color: '#e8402a', offset: [-10, 20] });

const lSide3 = lbl('Side 3', new THREE.Vector3(0, -1.15, 2.6), { italic: false, fontSize: '14px' });
const lSide4 = lbl('Side 4', new THREE.Vector3(DX, -0.75, 1.9), { italic: false, color: '#9a9a9a', fontSize: '14px' });
const lSide2 = lbl('Side 2', new THREE.Vector3(DX + 0.15, 2.15, 0.0), { italic: false, offset: [30, -12] });
const lSide1 = lbl('Side 1', new THREE.Vector3(DX + 0.5, -2.15, 0.6), { italic: false, offset: [34, 10] });

const lHeight = lbl('<i>l</i>', new THREE.Vector3(0, 0, L + 0.38), { offset: [-18, 0], fontSize: '16px' });
const lDepth = lbl('<i>l</i>', new THREE.Vector3(0, L / 2 + 0.32, L / 2), { offset: [0, -16], fontSize: '16px' });
const lThick = lbl('Δ<i>x</i>', new THREE.Vector3(DX / 2, -L / 2 - 0.52, 0), { offset: [0, 6], fontSize: '16px' });

const lXaxis = lbl('<i>x</i>', new THREE.Vector3(DX + AXEXT, TRI_Y, TRI_Z), { offset: [22, 14], fontSize: '16px' });
lbl('<i>y</i>', KEY.clone().add(new THREE.Vector3(0, 0.5, 0)), { offset: [0, -14], fontSize: '15px' });
lbl('<i>x</i>', KEY.clone().add(new THREE.Vector3(0.5, 0, 0)), { offset: [14, 8], fontSize: '15px' });
lbl('<i>z</i>', KEY.clone().add(new THREE.Vector3(0, 0, 0.5)), { offset: [-14, 10], fontSize: '15px' });

/* ── Layout update driven by Δx ──────────────────────────────────────────── */
function faceCenterWorld(f) {
  const n = f.n;
  return new THREE.Vector3(
    n.x !== 0 ? (n.x > 0 ? DX : 0) : DX / 2,
    n.y !== 0 ? n.y * L / 2 : 0,
    n.z !== 0 ? (n.z > 0 ? L : 0) : L / 2
  );
}
function placeNormal(f) {
  normalArrow.position.copy(faceCenterWorld(f));
  orientTo(normalArrow, f.n);
  normalArrow.visible = true;
}

let selected = null;

function applyDX(v) {
  DX = v;
  boxGroup.scale.set(v, 1, 1);
  boxGroup.position.set(v / 2, 0, L / 2);

  triadR.position.set(v, TRI_Y, TRI_Z);

  // As the two triads converge, push the right-hand labels further out so the
  // six field labels never collide.
  const sep = Math.max(0, Math.min(1, 1.15 - v));
  lEyR.pos.set(v, TRI_Y + ALEN, TRI_Z);
  lEyR.offset[0] = 8; lEyR.offset[1] = -16 - sep * 42;
  lExR.pos.set(v + ALEN, TRI_Y, TRI_Z);
  lExR.offset[0] = -6 + sep * 46; lExR.offset[1] = 20 + sep * 34;
  lEzR.pos.set(v, TRI_Y, TRI_Z + ALEN);
  lEzR.offset[0] = -10 - sep * 10; lEzR.offset[1] = 20 + sep * 32;
  lSide4.pos.set(v, -0.75, 1.9);

  dimThick.update(new THREE.Vector3(0, -L / 2 - 0.32, 0), new THREE.Vector3(v, -L / 2 - 0.32, 0), new THREE.Vector3(0, 0.15, 0));
  lThick.pos.set(v / 2, -L / 2 - 0.52, 0);

  const p0 = new THREE.Vector3(0, TRI_Y, TRI_Z), p1 = new THREE.Vector3(v + AXEXT, TRI_Y, TRI_Z);
  dashLine.geometry.setFromPoints([p0, p1]);
  dashLine.computeLineDistances();
  dashHead.position.set(v + AXEXT - 0.14, TRI_Y, TRI_Z);
  lXaxis.pos.set(v + AXEXT, TRI_Y, TRI_Z);

  leader2.update(new THREE.Vector3(v + 0.15, 2.15, 0.0),
                 new THREE.Vector3(v + 0.10, 2.00, 0.10),
                 new THREE.Vector3(0.45 * v, L / 2 + 0.03, 0.85));
  lSide2.pos.set(v + 0.15, 2.15, 0.0);
  leader1.update(new THREE.Vector3(v + 0.50, -2.15, 0.60),
                 new THREE.Vector3(v + 0.10, -2.02, 0.85),
                 new THREE.Vector3(0.50 * v, -L / 2 - 0.03, 0.95));
  lSide1.pos.set(v + 0.5, -2.15, 0.6);

  if (selected) placeNormal(selected);

  document.getElementById('dxVal').textContent = v.toFixed(2);
  document.getElementById('dxl').textContent = (v * L).toFixed(2);
}

applyDX(DX);

/* camera AFTER all geometry is placed at its default Δx */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, heightFraction: 0.9 });
document.getElementById('btnReset').style.display = '';

/* ── Face selection ──────────────────────────────────────────────────────── */
const ROW_IDS = ['rowS3', 'rowS4', 'rowS2', 'rowS1', 'rowSZ'];
const DEFAULT_INFO = 'Click any face of the box to highlight it, draw its outward normal, and read its flux term. Drag to orbit.';
function selectFace(f) {
  FACES.forEach(o => { o.mesh.material.opacity = 0; });
  ROW_IDS.forEach(id => { document.getElementById(id).style.background = 'transparent'; });
  selected = f;
  if (!f) {
    normalArrow.visible = false;
    document.getElementById('faceInfo').innerHTML = DEFAULT_INFO;
    return;
  }
  f.mesh.material.opacity = 0.5;
  placeNormal(f);
  document.getElementById(f.row).style.background = '#fdf1cd';
  document.getElementById('faceInfo').innerHTML =
    '<b>' + f.name + '</b> &nbsp; outward normal (' + f.n.x + ', ' + f.n.y + ', ' + f.n.z + ')<br>' +
    f.flux + '<br><span style="color:#555">' + f.body + '</span>';
}
FACES.forEach(f => registerInteractive(f.mesh, {
  title: f.name, tooltip: f.name + ' — ' + f.flux.replace(/<[^>]+>/g, ''),
  body: f.body, onClick: () => selectFace(f)
}));

/* ── Component visibility ────────────────────────────────────────────────── */
const comps = {
  x: { arrows: [triadL.userData.ax, triadR.userData.ax], labels: [lExL, lExR], rows: ['rowS3', 'rowS4'], cur: 1, target: 1 },
  y: { arrows: [triadL.userData.ay, triadR.userData.ay], labels: [lEyL, lEyR], rows: ['rowS2', 'rowS1'], cur: 1, target: 1 },
  z: { arrows: [triadL.userData.az, triadR.userData.az], labels: [lEzL, lEzR], rows: ['rowSZ'], cur: 1, target: 1 }
};
function applyComp(k) {
  const c = comps[k], o = c.cur;
  c.arrows.forEach(a => { a.userData.mat.opacity = o; a.visible = o > 0.02; });
  c.labels.forEach(l => { l.div.style.opacity = o; });
  c.rows.forEach(id => {
    const el = document.getElementById(id);
    el.style.color = c.target < 0.5 ? '#b3b3b3' : '#111';
    el.style.textDecoration = c.target < 0.5 ? 'line-through' : 'none';
  });
}

/* ── Controls ────────────────────────────────────────────────────────────── */
const dxSlider = document.getElementById('dxSlider');
let dxTarget = DX, dxCur = DX;
dxSlider.addEventListener('input', () => { dxTarget = parseFloat(dxSlider.value); dxCur = dxTarget; applyDX(dxCur); });

['x', 'y', 'z'].forEach(k => {
  const cb = document.getElementById('showE' + k);
  cb.addEventListener('change', () => { comps[k].target = cb.checked ? 1 : 0; applyComp(k); });
});

/* ── Demo steps ──────────────────────────────────────────────────────────── */
const STEPS = [
  { title: '1. The Gaussian box', text: 'A teal box of face area l × l and thickness Δx straddles the x-axis, the direction the wave travels. Identical red field triads are drawn at x and at x+Δx.', dx: 1.2, x: true, y: true, z: true, face: null },
  { title: '2. Only Ex crosses Sides 3 and 4', text: 'Hiding Ey and Ez leaves only the horizontal arrows. These are perpendicular to the two large faces, so Sides 3 and 4 carry the entire electric flux: −Ex(x,t)l² entering and +Ex(x+Δx,t)l² leaving.', dx: 1.2, x: true, y: false, z: false, face: 'S4' },
  { title: '3. Ey and Ez contribute nothing net', text: 'With only the vertical and lower-left arrows shown, the field runs parallel to the large faces and pierces the top/bottom (Sides 2, 1) and the two narrow faces in equal and opposite amounts, so those fluxes cancel.', dx: 1.2, x: false, y: true, z: true, face: 'S2' },
  { title: '4. Shrink Δx', text: 'Narrowing the box brings the two triads together: Ex(x+Δx,t) − Ex(x,t) becomes small, and with zero enclosed charge Gauss\'s law forces ∂Ex/∂x = 0 — the wave has no longitudinal electric component.', dx: 0.2, x: true, y: true, z: true, face: null }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  dxTarget = s.dx; dxSlider.value = String(s.dx);
  ['x', 'y', 'z'].forEach(k => {
    comps[k].target = s[k] ? 1 : 0;
    document.getElementById('showE' + k).checked = !!s[k];
    applyComp(k);
  });
  selectFace(s.face ? FACES.find(f => f.key === s.face) : null);
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));

/* ── Tween loop ──────────────────────────────────────────────────────────── */
function figTick() {
  requestAnimationFrame(figTick);
  if (Math.abs(dxCur - dxTarget) > 0.0015) {
    dxCur += (dxTarget - dxCur) * 0.16;
